INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('bench', 'پرس سینه هالتر', 'Barbell Bench Press', 'chest', 0, 'barbell', 'حرکت اصلی امروز. کتف‌ها جمع و پایین. هالتر را در ۲ تا ۳ ثانیه تا روی سینه بیاور، مکث کوتاه، بعد فشار بده.', 'Main lift today. Shoulder blades squeezed and down. Lower the bar to your chest over 2–3 seconds, pause briefly, then press.', 'seed', 'bench', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('incline_db', 'پرس بالا سینه دمبل', 'Incline Dumbbell Press', 'chest', 0, 'dumbbell', 'زاویه‌ی نیمکت ۳۰ تا ۴۵ درجه. دمبل‌ها را تا کشش کامل سینه پایین بیاور.', 'Bench at 30–45°. Lower the dumbbells until your chest is fully stretched.', 'seed', 'incline_db', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('rdl', 'ددلیفت رومانیایی', 'Romanian Deadlift', 'hamstrings', 1, 'barbell', 'زانو کمی خم. لگن را به عقب بفرست تا کشش پشت ران را حس کنی. هالتر نزدیک پا.', 'Knees slightly bent. Push your hips back until you feel the stretch in your hamstrings. Keep the bar close to your legs.', 'seed', 'rdl', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('cable_row', 'زیربغل کابل نشسته', 'Seated Cable Row', 'back_upper', 0, 'cable', 'کمر صاف. دستگیره را به شکم بکش و کتف‌ها را به هم نزدیک کن.', 'Back straight. Pull the handle to your stomach and squeeze your shoulder blades together.', 'seed', 'cable_row', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('lateral', 'نشر جانب', 'Dumbbell Lateral Raise', 'shoulders_side', 0, 'dumbbell', 'دمبل‌ها را تا ارتفاع شانه بالا بیاور، بدون تاب دادن بدن.', 'Raise the dumbbells to shoulder height without swinging your body.', 'seed', 'lateral', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('facepull', 'فیس‌پول', 'Face Pull', 'rear_delts', 0, 'cable', 'طناب را به سمت صورت بکش و دست‌ها را از هم باز کن. آرنج‌ها بالا.', 'Pull the rope toward your face and spread your hands apart. Elbows high.', 'seed', 'facepull', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('squat', 'اسکوات هالتر', 'Barbell Back Squat', 'quads', 1, 'barbell', 'حرکت اصلی امروز. پاها کمی بازتر از شانه. تا موازی شدن ران با زمین پایین برو، زانو هم‌جهت پنجه.', 'Main lift today. Feet a little wider than your shoulders. Go down until your thighs are parallel to the floor, knees in line with your toes.', 'seed', 'squat', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('leg_press', 'پرس پا', 'Leg Press', 'quads', 1, 'machine', 'کمر و لگن به پشتی چسبیده. تا جایی پایین بیاور که لگن از پشتی جدا نشود، زانو قفل نشود.', 'Lower back and hips stay on the pad. Go only as low as your hips stay down, and don''t lock your knees.', 'seed', 'leg_press', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('incline_bb', 'پرس بالا سینه هالتر', 'Incline Barbell Bench Press', 'chest', 0, 'barbell', 'زاویه‌ی ۳۰ درجه. هالتر را تا بالای سینه بیاور، کتف‌ها جمع.', 'Bench at 30°. Lower the bar to your upper chest, shoulder blades squeezed.', 'seed', 'incline_bb', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('pulldown', 'لت‌پول‌داون', 'Lat Pulldown', 'back_lats', 0, 'cable', 'سینه بالا، میله را تا بالای سینه بکش. آرنج‌ها به سمت پایین و پهلو.', 'Chest up, pull the bar to your upper chest. Drive your elbows down and to your sides.', 'seed', 'pulldown', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('calf_stand', 'ساق پا ایستاده', 'Standing Calf Raise', 'calves', 1, 'machine', 'پاشنه را کامل پایین بیاور و بالا یک ثانیه مکث کن.', 'Lower your heels all the way and pause for a second at the top.', 'seed', 'calf_stand', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('plank', 'پلانک', 'Plank', 'core', 0, 'bodyweight', 'بدن در یک خط صاف. شکم و باسن سفت، لگن نیفتد.', 'Body in one straight line. Abs and glutes tight; don''t let your hips sag.', 'seed', 'plank', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('cs_row', 'زیربغل دمبل روی نیمکت شیب‌دار', 'Chest-Supported Dumbbell Row', 'back_upper', 0, 'dumbbell', 'حرکت اصلی امروز. سینه روی نیمکت ۳۰ تا ۴۵ درجه. دمبل‌ها را به سمت لگن بکش و کتف‌ها را جمع کن؛ کمر استراحت می‌کند.', 'Main lift today. Chest on a 30–45° bench. Pull the dumbbells toward your hips and squeeze your shoulder blades; your lower back rests.', 'seed', 'cs_row', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('pullup', 'بارفیکس', 'Pull-Up / Assisted Pull-Up', 'back_lats', 0, 'bodyweight', 'از آویزان کامل شروع کن و چانه را بالای میله ببر. با دستگاه کمکی، وزن کمکی را منفی بنویس (مثلاً ‎-40‎).', 'Start from a dead hang and bring your chin over the bar. On the assisted machine, log the assistance weight as a negative number (e.g. -40).', 'seed', 'pullup', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('bulgarian', 'اسکوات بلغاری', 'Bulgarian Split Squat', 'quads', 1, 'dumbbell', 'پای عقب روی نیمکت. مستقیم پایین برو تا ران جلو موازی زمین شود.', 'Back foot on the bench. Go straight down until your front thigh is parallel to the floor.', 'seed', 'bulgarian', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('fly', 'قفسه‌ی کابل', 'Cable Chest Fly', 'chest', 0, 'cable', 'آرنج کمی خم و ثابت. در ست آخر چند تکرار نیمه در حالت کشیده (Partials) بزن.', 'Elbows slightly bent and fixed. On the last set, add a few partial reps in the stretched position.', 'seed', 'fly', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('curl', 'جلو بازو دمبل', 'Dumbbell Biceps Curl', 'biceps', 0, 'dumbbell', 'آرنج کنار بدن و ثابت. آرام پایین بیاور.', 'Elbows at your sides and still. Lower slowly.', 'seed', 'curl', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('oh_tri', 'پشت بازو کابل از بالای سر', 'Overhead Cable Triceps Extension', 'triceps', 0, 'cable', 'آرنج‌ها کنار سر و ثابت. فقط ساعد حرکت کند و پایین کشش کامل بگیر.', 'Elbows by your head and still. Only your forearms move; get a full stretch at the bottom.', 'seed', 'oh_tri', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('deadlift', 'ددلیفت', 'Conventional Deadlift', 'glutes', 1, 'barbell', 'حرکت اصلی امروز. هالتر روی وسط پا. کمر صاف، سینه بالا. با فشار پاها بلند شو، نه با کشیدن کمر.', 'Main lift today. Bar over mid-foot. Back flat, chest up. Stand up by pushing with your legs, not by pulling with your back.', 'seed', 'deadlift', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('ohp', 'پرس سرشانه ایستاده', 'Standing Overhead Press', 'shoulders_front', 0, 'barbell', 'باسن و شکم سفت، کمر قوس زیاد نگیرد. هالتر در خط صاف بالای سر برود.', 'Glutes and abs tight, no big arch in your lower back. Press the bar in a straight line overhead.', 'seed', 'ohp', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('leg_curl', 'پشت ران دستگاه', 'Lying Leg Curl', 'hamstrings', 1, 'machine', 'لگن روی نیمکت بماند. آرام پایین بیاور.', 'Keep your hips on the bench. Lower slowly.', 'seed', 'leg_curl', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('knee_raise', 'بالا آوردن زانو آویزان', 'Hanging Knee Raise', 'core', 0, 'bodyweight', 'بدون تاب. زانوها را تا سینه بالا بیاور و آرام پایین بیاور.', 'No swinging. Bring your knees up to your chest and lower them slowly.', 'seed', 'knee_raise', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('calf_seated', 'ساق پا نشسته', 'Seated Calf Raise', 'calves', 1, 'machine', 'دامنه‌ی کامل و مکث در بالا.', 'Full range of motion and a pause at the top.', 'seed', 'calf_seated', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('row', 'زیربغل هالتر خم', 'Barbell Bent-Over Row', 'back_upper', 0, 'barbell', 'کمر صاف، لگن به عقب. هالتر را به سمت ناف بکش، بدون تاب دادن بدن.', 'Back flat, hips back. Pull the bar toward your navel without swinging your body.', 'seed', 'row', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('lunge', 'لانج با دمبل', 'Walking Lunge', 'quads', 1, 'dumbbell', 'بالاتنه صاف. زانوی عقب نزدیک زمین، زانوی جلو بالای مچ پا.', 'Upper body upright. Back knee close to the floor, front knee over your ankle.', 'seed', 'lunge', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('dips', 'دیپ سینه', 'Chest Dips', 'chest', 0, 'bodyweight', 'بدن رو به جلو تا فشار روی سینه بیاید. درد شانه = جایگزین با پرس سینه دمبل. در ست آخر Partials.', 'Lean forward so the load goes to your chest. If your shoulder hurts, swap for the dumbbell bench press. Partials on the last set.', 'seed', 'dips', 'strength');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa, cue_en, source, source_id, category) VALUES ('rope_pushdown', 'پشت بازو طناب', 'Triceps Rope Pushdown', 'triceps', 0, 'cable', '', NULL, 'seed', 'rope_pushdown', 'strength');
